<script setup>
import {useI18n} from 'vue-i18n'
import {weatherKind,weatherMetric as metric} from './weather.js'
import WeatherIcon from './WeatherIcon.vue'
import {observationExpired} from './system-format.js'
import {stamp} from './format.js'
defineProps(['data','clock','connected'])
const {t,locale}=useI18n()
const number=n=>n===null?t('widget.unknown'):n.toLocaleString(locale.value,{maximumFractionDigits:0})
const hour=n=>n===null?'—':new Date(n*1000).toLocaleTimeString(locale.value,{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Shanghai'})
</script>
<template><article class="weather-widget"><div class="panel-heading"><h2>{{t('weather.title')}}</h2><span class="badge">{{t('weather.model')}}</span></div><p v-if="!data?.observations?.some(o=>o.provider==='weather')" class="muted">{{t('weather.empty')}}</p><section v-for="item in (data?.observations||[]).filter(o=>o.provider==='weather')" :key="item.entity_id"><div class="system-target"><span>{{item.entries?.[0]?.title||item.entity_id}}</span><span class="data-state">{{t(!connected?'status.cached':observationExpired(item,clock)?'system.expired':item.status==='ok'?'system.fresh':'system.unavailable')}}</span></div><template v-if="item.status==='ok'"><div class="weather-current"><WeatherIcon :kind="weatherKind(metric(item,'code'))"/><div><strong>{{number(metric(item,'temperature'))}}<small>°C</small></strong><p>{{t('weather.'+weatherKind(metric(item,'code')))}}</p></div></div><p class="weather-summary">{{t('weather.feels')}} {{number(metric(item,'feels'))}}° · {{number(metric(item,'low'))}}°–{{number(metric(item,'high'))}}°<br>{{t('weather.rainProbability')}} {{number(metric(item,'rain'))}}%</p><div class="weather-hours"><div v-for="j in [0,1,2]" :key="j"><span>{{hour(metric(item,`hour.${j}.time`))}}</span><WeatherIcon :kind="weatherKind(metric(item,`hour.${j}.code`))"/><strong>{{number(metric(item,`hour.${j}.temperature`))}}°</strong></div></div><p class="source-line">{{t('weather.modelTime')}}: {{hour(metric(item,'model_time'))}} · Asia/Shanghai</p></template><p class="source-line">{{t('system.time')}}: {{stamp(item.collected_at,locale,t('widget.notCollected'))}}</p></section><p class="source-line weather-credit"><a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">Weather data by Open-Meteo.com</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a></p></article></template>
